// fixtureCopy copies an e2e workspace template (generated by the
// Playwright global setup under .playwright/workspaces/) into a temp
// dir with isolated git, or skips.
func fixtureCopy(t *testing.T, name string) string {
	t.Helper()
	src, _ := filepath.Abs(filepath.Join("..", "..", "..", ".playwright", "workspaces", name))
	if _, err := os.Stat(filepath.Join(src, "req")); err != nil {
		t.Skipf("%s is missing: the Playwright global setup generates it (run the e2e suite once)", src)
	}
	tmp := t.TempDir()
	isolateGit(t, tmp)
	real, err := filepath.EvalSymlinks(tmp)
	if err != nil {
		t.Fatal(err)
	}
	dir := filepath.Join(real, name)
	if out, err := exec.Command("cp", "-Rp", src, dir).CombinedOutput(); err != nil {
		t.Fatalf("copy %s: %v %s", src, err, out)
	}
	return dir
}

func openLibrary(t *testing.T, dir string, noGit bool) *Library {
	t.Helper()
	lib, err := library.Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	l, err := NewLibrary(context.Background(), lib, LibraryOptions{NoGit: noGit, Logf: t.Logf, Now: func() time.Time { return time.Date(2026, 10, 13, 9, 0, 0, 0, time.UTC) }}, nil, false)
	if err != nil {
		t.Fatal(err)
	}
	return l
}

// runAll runs every analysis of an area and returns path → outcome (the
// HTTP status and the envelope's data and errors).
func runAll(t *testing.T, h http.Handler, ws, dir string) map[string]string {
	t.Helper()
	code, body := call(t, h, http.MethodGet, "/api/w/"+ws+"/files", nil)
	if code != http.StatusOK {
		t.Fatalf("files: %d %v", code, body)
	}
	out := map[string]string{}
	for _, f := range body["files"].([]any) {
		f := f.(map[string]any)
		switch f["kind"] {
		case "request", "compose", "facet", "chain":
		default:
			continue
		}
		p := f["path"].(string)
		text, err := os.ReadFile(filepath.Join(dir, filepath.FromSlash(p)))
		if err != nil {
			t.Fatal(err)
		}
		code, env := libRun(t, h, ws, p, string(text))
		outcome := map[string]any{"code": code}
		if code == http.StatusOK {
			outcome["data"], outcome["errors"] = env["data"], env["errors"]
		} else {
			outcome["error"] = env["error"]
		}
		if f["kind"] == "request" {
			// The cohort node's preview too (the studio's own resolution).
			code, prev := call(t, h, http.MethodPost, "/api/w/"+ws+"/preview", map[string]any{"path": p, "request": json.RawMessage(text), "node": "cohort"})
			delete(prev, "elapsed_ms")
			delete(prev, "cached")
			outcome["preview"] = map[string]any{"code": code, "body": prev}
		}
		b, _ := json.Marshal(outcome)
		out[p] = string(b)
	}
	return out
}

// TestMigrateFixtures migrates copies of the e2e workspaces and checks
// that every analysis gives exactly the result it gave before, served
// by the same server (no restart).
func TestMigrateFixtures(t *testing.T) {
	for _, name := range []string{"ab-test-readout", "retail-chain", "privacy-safe-sharing"} {
		t.Run(name, func(t *testing.T) {
			dir := fixtureCopy(t, name)
			l := openLibrary(t, dir, false)
			slug := library.Slugify(name)
			before := runAll(t, l, slug, dir)
			if len(before) == 0 {
				t.Fatal("no analyses")
			}
			ok, previews := 0, 0
			for _, o := range before {
				if strings.HasPrefix(o, `{"code":200`) {
					ok++
				}
				if strings.Contains(o, `"status":"ok","verb"`) {
					previews++
				}
			}
			t.Logf("%d analyses, %d run and %d cohort previews succeed before the migration", len(before), ok, previews)
			if ok == 0 || previews == 0 {
				t.Fatal("nothing runs or previews before the migration")
			}

			code, plan := call(t, l, http.MethodGet, "/api/migration/plan", nil)
			if code != http.StatusOK || plan["migratable"] != true {
				t.Fatalf("plan: %d %v", code, plan)
			}
			code, res := call(t, l, http.MethodPost, "/api/migration/apply", map[string]any{"plan_id": plan["plan_id"]})
			if code != http.StatusOK || res["mode"] != "library" || res["restart_required"] != false {
				t.Fatalf("apply: %d %v", code, res)
			}
			// The same handler now serves the library.
			if _, h := call(t, l, http.MethodGet, "/api/health", nil); h["mode"] != "library" {
				t.Fatalf("health after the migration: %v", h)
			}
			if _, lb := call(t, l, http.MethodGet, "/api/library", nil); lb["default"] != slug {
				t.Fatalf("library: %v", lb)
			}
			if _, p := call(t, l, http.MethodGet, "/api/migration/plan", nil); p["reason"] != "already_library" {
				t.Fatalf("plan after: %v", p)
			}

			wsDir := filepath.Join(dir, "workspaces", slug)
			after := runAll(t, l, slug, wsDir)
			// analyses/x.json was req/x.json.
			mapped := map[string]string{}
			for p, o := range after {
				if !strings.HasPrefix(p, "analyses/") {
					t.Errorf("analysis outside analyses/: %s", p)
				}
				// Envelopes name the cohort file they read
				// (metadata.cohort_file): it is now under cohorts/.
				mapped["req/"+strings.TrimPrefix(p, "analyses/")] = strings.ReplaceAll(o, `"cohorts/`, `"`)
			}
			if !reflect.DeepEqual(keys(before), keys(mapped)) {
				t.Fatalf("analyses before %v, after %v", keys(before), keys(mapped))
			}
			for p, o := range before {
				if mapped[p] != o {
					t.Errorf("%s: before %.300s\nafter %.300s", p, o, mapped[p])
				}
			}
			// Cohort refs all name the workspace's cohorts/, except the
			// ones the plan warned about (cohorts the fixture lacks).
			warned := map[string]bool{}
			for _, w := range plan["warnings"].([]any) {
				w := w.(map[string]any)
				if w["code"] != "ref_missing" {
					t.Errorf("unexpected warning %v", w)
				}
				warned["analyses/"+strings.TrimPrefix(w["path"].(string), "req/")] = true
			}
			for p := range after {
				text, _ := os.ReadFile(filepath.Join(wsDir, filepath.FromSlash(p)))
				if strings.Contains(string(text), `"data_dir": "."`) && !warned[p] {
					t.Errorf("%s still has a legacy data_dir", p)
				}
			}
			// History: the workspace repository is the old one, and every
			// analysis follows back to its legacy path.
			for p := range after {
				out, err := exec.Command("git", "-C", wsDir, "log", "--follow", "--format=%s", "--", p).Output()
				if err != nil {
					t.Fatal(err)
				}
				got := strings.TrimPrefix(strings.TrimSpace(string(out)), "studio: migrate cohort references\n")
				if got != "studio: migrate to library layout\nstudio: initial snapshot" {
					t.Errorf("history of %s = %q", p, out)
				}
			}
			if out, _ := exec.Command("git", "-C", dir, "log", "--format=%s").Output(); strings.TrimSpace(string(out)) != "studio: initial snapshot" {
				t.Errorf("global repository log = %q", out)
			}
		})
	}
}

// TestMigrateNested migrates a casebook-shaped folder: the three e2e
// workspaces under showcase/<case>/ (requests in showcase/<case>/req/,
// cohorts beside req/). Every analysis keeps its relative path under
// analyses/ and gives the same results and previews.
func TestMigrateNested(t *testing.T) {
	var dir string
	for i, name := range []string{"ab-test-readout", "retail-chain", "privacy-safe-sharing"} {
		src := fixtureCopy(t, name)
		if i == 0 {
			dir = filepath.Join(filepath.Dir(filepath.Dir(src)), "casebook")
		}
		if err := os.MkdirAll(filepath.Join(dir, "showcase"), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.Rename(src, filepath.Join(dir, "showcase", name)); err != nil {
			t.Fatal(err)
		}
	}
	isolateGit(t, filepath.Dir(dir))
	l := openLibrary(t, dir, false)
	before := runAll(t, l, "casebook", dir)
	ok := 0
	for _, o := range before {
		if strings.HasPrefix(o, `{"code":200`) {
			ok++
		}
	}
	if len(before) != 30 || ok < 25 {
		t.Fatalf("%d analyses, %d run before the migration", len(before), ok)
	}
	_, plan := call(t, l, http.MethodGet, "/api/migration/plan", nil)
	if plan["migratable"] != true {
		t.Fatalf("plan: %v", plan)
	}
	code, res := call(t, l, http.MethodPost, "/api/migration/apply", map[string]any{"plan_id": plan["plan_id"]})
	if code != http.StatusOK {
		t.Fatalf("apply: %d %v", code, res)
	}
	wsDir := filepath.Join(dir, "workspaces", "casebook")
	if _, err := os.Stat(filepath.Join(wsDir, "cohorts", "showcase", "retail-chain", "orders.pulse")); err != nil {
		t.Fatal(err)
	}
	after := runAll(t, l, "casebook", wsDir)
	mapped := map[string]string{}
	for p, o := range after {
		mapped[strings.TrimPrefix(p, "analyses/")] = strings.ReplaceAll(o, `"cohorts/`, `"`)
	}
	if !reflect.DeepEqual(keys(before), keys(mapped)) {
		t.Fatalf("analyses before %v, after %v", keys(before), keys(mapped))
	}
	for p, o := range before {
		if mapped[p] != o {
			t.Errorf("%s: before %.300s\nafter %.300s", p, o, mapped[p])
		}
	}
}

func keys(m map[string]string) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	sort.Strings(out)
	return out
}

func TestMigrationNoGit(t *testing.T) {
	dir := t.TempDir()
	writeFiles(t, dir, map[string]string{"req/a.json": `{"cohort": {"filename": "a.pulse", "data_dir": "."}}`, "a.pulse": "x"})
	l := openLibrary(t, dir, true)
	_, plan := call(t, l, http.MethodGet, "/api/migration/plan", nil)
	if plan["migratable"] != false || plan["reason"] != "no_git" || plan["message"] == "" {
		t.Fatalf("plan: %v", plan)
	}
	code, res := call(t, l, http.MethodPost, "/api/migration/apply", nil)
	if code != http.StatusConflict || res["error"].(map[string]any)["code"] != "not_migratable" {
		t.Fatalf("apply: %d %v", code, res)
	}
	if _, err := os.Stat(filepath.Join(dir, "req", "a.json")); err != nil {
		t.Fatal("legacy folder touched")
	}
}

func TestMigrationPlanChanged(t *testing.T) {
	dir := t.TempDir()
	isolateGit(t, dir)
	writeFiles(t, dir, map[string]string{"req/a.json": `{"cohort": {"filename": "a.pulse", "data_dir": "."}}`, "a.pulse": "x"})
	l := openLibrary(t, dir, false)
	_, plan := call(t, l, http.MethodGet, "/api/migration/plan", nil)
	writeFiles(t, dir, map[string]string{"req/b.json": `{"cohort": {"filename": "a.pulse", "data_dir": "."}}`})
	code, res := call(t, l, http.MethodPost, "/api/migration/apply", map[string]any{"plan_id": plan["plan_id"]})
	if code != http.StatusConflict || res["error"].(map[string]any)["code"] != "plan_changed" {
		t.Fatalf("apply: %d %v", code, res)
	}
	code, res = call(t, l, http.MethodPost, "/api/migration/apply", map[string]any{})
	if code != http.StatusOK {
		t.Fatalf("apply: %d %v", code, res)
	}
	if code, _ := call(t, l, http.MethodPost, "/api/migration/apply", nil); code != http.StatusConflict {
		t.Fatalf("second apply: %d", code)
	}
}

func writeFiles(t *testing.T, dir string, files map[string]string) {
	t.Helper()
	for rel, text := range files {
		p := filepath.Join(dir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(text), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}
